const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

var ans=0,met=false;

rl.on('line', (input) => {
    let temp=input.match(/B/g);
   // console.log("temp= "+temp);
    if(/*temp.length == 8*/ input=="BBBBBBBB")
       ans++;
    else if(!met){
      if(temp!=null)  
          ans+=temp.length;
       met=true;
    }

  }).on('close',function(){
      console.log(ans);
  });
